<?php
require_once __DIR__.'/../includes/member.php';$user=require_login();if($user['role']==='admin')redirect('admin/dashboard.php');
$cutoff=(new DateTimeImmutable('now'))->modify('+2 days')->format('Y-m-d H:i:s');
if($_SERVER['REQUEST_METHOD']==='POST'){
    $loan=one("SELECT br.*,COALESCE((SELECT SUM(e.duration_days) FROM extensions e WHERE e.borrowing_id=br.id AND e.status='approved'),0) extension_days FROM borrowings br WHERE br.id=? AND br.user_id=? AND br.status='active'",[(int)($_POST['borrowing_id']??0),$user['id']]);
    $duration=(int)($_POST['duration_days']??0);$reason=trim($_POST['reason']??'');
    $pending=$loan?one("SELECT id FROM extensions WHERE borrowing_id=? AND status='pending'",[$loan['id']]):null;
    $eligible=$loan&&strtotime($loan['due_date'])>=time()+2*86400&&(int)$loan['renew_count']<6&&(int)$loan['extension_days']+$duration<=53;
    if(!$eligible||$pending||!in_array($duration,[3,7,14],true)||$reason===''){flash('Ajuan harus dibuat paling lambat H-2, maksimal enam kali dan total masa pinjam dua bulan.','error');redirect('member/perpanjangan.php');}
    $requestedAt=(new DateTimeImmutable('now'))->format('Y-m-d H:i:s');execute('INSERT INTO extensions(user_id,borrowing_id,reason,duration_days,requested_at) VALUES(?,?,?,?,?)',[$user['id'],$loan['id'],$reason,$duration,$requestedAt]);flash('Ajuan perpanjangan sudah diterima dan menunggu admin merespon.');redirect('member/perpanjangan.php?submitted=1');
}
$loans=rows("SELECT br.id,br.due_date,br.renew_count,b.title,b.book_id,COALESCE((SELECT SUM(e.duration_days) FROM extensions e WHERE e.borrowing_id=br.id AND e.status='approved'),0) extension_days FROM borrowings br JOIN books b ON b.id=br.book_id WHERE br.user_id=? AND br.status='active' AND br.due_date>=? AND br.renew_count<6 AND NOT EXISTS(SELECT 1 FROM extensions e WHERE e.borrowing_id=br.id AND e.status='pending') ORDER BY br.due_date",[$user['id'],$cutoff]);
member_start('Ajukan Perpanjangan',$user,'peminjaman.php'); ?>
<section class="member-section"><span class="member-kicker">PERMINTAAN MASA PINJAM</span><h1>Perpanjangan</h1><?php if(isset($_GET['submitted'])):?><div class="notice extension-success">Ajuan perpanjangan sudah diterima dan menunggu admin merespon.</div><div class="extension-history-actions"><a class="member-see-all" href="<?=e(url('member/Riwayat.php'))?>">Lihat riwayat ajuan</a></div><?php else:?><form class="member-form visible" method="post"><label>Buku yang dipinjam<select name="borrowing_id" id="extension-book" required><option value="">Pilih buku</option><?php foreach($loans as $loan):?><option value="<?=(int)$loan['id']?>" data-used-days="<?=(int)$loan['extension_days']?>" <?=((int)($_GET['borrowing_id']??0)===(int)$loan['id']?'selected':'')?>><?=e($loan['title'])?> · <?=e($loan['book_id'])?> — jatuh tempo <?=date_id($loan['due_date'])?></option><?php endforeach;?></select></label><label>Alasan perpanjangan<textarea name="reason" rows="4" required></textarea></label><label>Durasi perpanjangan<select name="duration_days" id="extension-duration" required><option value="">Pilih durasi</option><option value="3">3 hari</option><option value="7">7 hari</option><option value="14">14 hari</option></select></label><button type="submit" <?=(!$loans?'disabled':'')?>>Kirim ajuan</button><?php if(!$loans):?><p>Tidak ada buku yang memenuhi syarat. Pengajuan harus paling lambat H-2, maksimal 6 kali dengan total masa pinjam paling lama 2 bulan.</p><?php endif;?></form><?php endif;?></section>
<script>(()=>{const book=document.getElementById('extension-book'),duration=document.getElementById('extension-duration');if(!book||!duration)return;function sync(){const used=Number(book.selectedOptions[0]?.dataset.usedDays||0);for(const option of duration.options){if(option.value)option.disabled=used+Number(option.value)>53}}book.addEventListener('change',sync);sync()})();</script><?php member_end(); ?>
